import { ChangeDetectionStrategy, Component, computed } from "@angular/core";
import { PillComponent } from "./pill.component";

/** A pill for a state of the screen: it reads its label out loud and marks the hint with a question mark. */
@Component({
    selector: "app-status-pill",
    changeDetection: ChangeDetectionStrategy.OnPush,
    template: `<span class="pill status" [class]="variant()" [attr.aria-label]="spoken()">{{ label() }}@if (!disableTooltip()) {<span class="hint">?</span>}</span>`
})
export class StatusPillComponent extends PillComponent {
    readonly spoken = computed(() => this.disableTooltip() ? this.label() : this.label() + ", a hint is available");
}
import { ChangeDetectionStrategy, Component, Input } from "@angular/core";
import type { PillVariant } from "./pill.component";

/** The old pill of the reports screen. A component of its own with its own inputs: it does not extend PillComponent. */
@Component({
    selector: "app-pill-legacy",
    changeDetection: ChangeDetectionStrategy.OnPush,
    template: `<span class="pill legacy" [class]="variant">{{ label }}@if (!disableTooltip) {<span class="hint">i</span>}</span>`
})
export class PillLegacyComponent {
    @Input() label = "";
    @Input() variant: PillVariant = "info";
    @Input() disableTooltip = false;
}
import { ChangeDetectionStrategy, Component, viewChild, ViewContainerRef } from "@angular/core";
import { CardComponent } from "./card.component";
import { FancyPillComponent } from "./fancy-pill.component";
import { PillComponent } from "./pill.component";

/** Adds pills and cards at run time, for lists whose length no template knows. */
@Component({
    selector: "app-pill-tray",
    changeDetection: ChangeDetectionStrategy.OnPush,
    template: `<ng-container #slot />`
})
export class PillTrayComponent {
    private readonly slot = viewChild.required("slot", { read: ViewContainerRef });

    addPill(label: string, quiet = false): void {
        const pill = this.slot().createComponent(PillComponent);
        pill.setInput("label", label);
        pill.setInput("disableTooltip", quiet);
    }

    addFancyPill(label: string, icon: string): void {
        const pill = this.slot().createComponent(FancyPillComponent);
        pill.setInput("label", label);
        pill.setInput("icon", icon);
        pill.setInput("disableTooltip", true);
    }

    addCard(heading: string): void {
        const card = this.slot().createComponent(CardComponent);
        card.setInput("heading", heading);
        card.setInput("disableTooltip", true);
    }
}
import { booleanAttribute, Directive, input } from "@angular/core";

/**
 * Marks any element as having a hint. It has its own switch, hintDisabled,
 * and never looks at the disableTooltip flag of the card around it.
 */
@Directive({
    selector: "[appHint]",
    host: { "[class.has-hint]": "!hintDisabled()", "[attr.title]": "hintDisabled() ? null : appHint()" }
})
export class HintDirective {
    readonly appHint = input("");
    readonly hintDisabled = input(false, { transform: booleanAttribute });
}
import { booleanAttribute, ChangeDetectionStrategy, Component, input } from "@angular/core";

@Component({
    selector: "app-card",
    changeDetection: ChangeDetectionStrategy.OnPush,
    template: `<section class="card" [attr.title]="disableTooltip() ? null : heading()"><h3>{{ heading() }}</h3><ng-content /></section>`
})
export class CardComponent {
    readonly heading = input("");
    /** disableTooltip: the card shows no title hint. */
    readonly disableTooltip = input(false, { transform: booleanAttribute });
}
import { ChangeDetectionStrategy, Component } from "@angular/core";
import { CardComponent } from "../../lib/card.component";
import { FancyPillComponent } from "../../lib/fancy-pill.component";
import { PillComponent, type PillVariant } from "../../lib/pill.component";

@Component({
    selector: "app-feature-1",
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [ PillComponent, FancyPillComponent, CardComponent ],
    template: `
        <app-card heading="Feature 1" disableTooltip>
            <p class="hint">This card sets disableTooltip: its title shows no hint.</p>
            <app-pill label="Plain" disableTooltip />
            <app-pill variant="success" label="Active" [disableTooltip]="!isActive" />
            <app-pill [label]="count > 3 ? 'Many' : title" [disableTooltip]="count > 3" />
            <app-pill
                [variant]="isActive ? 'success' : 'warning'"
                label="Multi-line"
                [disableTooltip]="isActive">
            </app-pill>
            @if (isActive) {
                <app-pill [variant]="statusVariant" label="Nested" [disableTooltip]="false" />
            }
            <app-fancy-pill label="Fancy" icon="star" [disableTooltip]="!isActive" />
            @if (disableTooltip) {
                <small>Hints are switched off on this screen</small>
            }
        </app-card>
    `
})
export class Feature001Component {
    isActive = false;
    count = 1;
    title = "Title 1";
    statusVariant: PillVariant = "success";
    // disableTooltip is the switch of this screen; the card and the pills have theirs
    disableTooltip = true;
}
