const fs=require('fs'),path=require('path');
const OLD='disableTooltip',NEW='hideHint';
function walk(d,o=[]){for(const f of fs.readdirSync(d)){const p=path.join(d,f);fs.statSync(p).isDirectory()?walk(p,o):o.push(p)}return o}
const files=walk('src').filter(f=>/\.(ts|html|css)$/.test(f));
let total=0;
function renameTags(s){
  const re=/<app-(pill|fancy-pill|status-pill)(?![\w-])/g;let out='',last=0,m;
  while((m=re.exec(s))){
    let i=m.index+m[0].length,q=null;
    for(;i<s.length;i++){const c=s[i];if(q){if(c===q)q=null}else if(c==='"'||c==="'")q=c;else if(c==='>')break;}
    // tokenise attributes outside quotes
    let tag=s.slice(m.index,i),r='',q2=null;
    for(let j=0;j<tag.length;j++){const c=tag[j];
      if(q2){r+=c;if(c===q2)q2=null;continue}
      if(c==='"'||c==="'"){q2=c;r+=c;continue}
      if(tag.startsWith(OLD,j)&&/[\s\[]/.test(tag[j-1])&&!/\w/.test(tag[j+OLD.length]||'')){r+=NEW;j+=OLD.length-1;total++;continue}
      r+=c}
    out+=s.slice(last,m.index)+r;last=i;re.lastIndex=i;
  }
  return out+s.slice(last);
}
for(const f of files){
  let s=fs.readFileSync(f,'utf8'),o=s;
  const n=f.replace(/\\/g,'/');
  if(n.endsWith('.css')){s=s.replace(/(app-(?:pill|fancy-pill|status-pill)\[)disableTooltip\]/g,'$1hideHint]')}
  else{
    s=renameTags(s);
    const exprs=[/\b(this\.firstPill\(\)\??\.)disableTooltip\b/g,/\b(this\.fancy\(\)\??\.)disableTooltip\b/g,/(?<![.\w])((?:fancy|pill|fancyRef)\.)disableTooltip\b/g];
    for(const e of exprs)s=s.replace(e,'$1hideHint');
    if(/lib\/(pill|fancy-pill|status-pill)\.component\.ts$/.test(n)){
      s=s.replace(/readonly disableTooltip = input/,'readonly hideHint = input').replace(/!disableTooltip\(\)/g,'!hideHint()').replace(/this\.disableTooltip\(\)/g,'this.hideHint()');
    }
    if(n.endsWith('lib/pill-tray.component.ts')){
      s=s.replace(/(createComponent\((?:PillComponent|FancyPillComponent)\);[\s\S]*?)pill\.setInput\("disableTooltip"/g,'$1pill.setInput("hideHint"');
    }
  }
  if(s!==o){fs.writeFileSync(f,s)}
}
console.log('tag attrs',total);
